package main

// Low-level terminal handling using only the Go standard library.

import (
	"os"
	"os/signal"
	"syscall"
	"unsafe"
)

type termios = syscall.Termios

const (
	tcgets  = 0x5401
	tcsets  = 0x5402
	tiocgwinsz = 0x5413
)

type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}

func ioctl(fd uintptr, req uintptr, arg unsafe.Pointer) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(arg))
	if errno != 0 {
		return errno
	}
	return nil
}

func getWinsize(fd uintptr) (int, int, error) {
	var ws winsize
	if err := ioctl(fd, tiocgwinsz, unsafe.Pointer(&ws)); err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}

func makeRaw(fd uintptr) (*termios, error) {
	var old termios
	if err := ioctl(fd, tcgets, unsafe.Pointer(&old)); err != nil {
		return nil, err
	}
	raw := old
	raw.Iflag &^= syscall.IXON | syscall.ICRNL | syscall.BRKINT | syscall.INPCK | syscall.ISTRIP
	raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Oflag &^= syscall.OPOST
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := ioctl(fd, tcsets, unsafe.Pointer(&raw)); err != nil {
		return nil, err
	}
	return &old, nil
}

func restore(fd uintptr, old *termios) {
	ioctl(fd, tcsets, unsafe.Pointer(old))
}

// watchWinch returns a channel that fires on SIGWINCH.
func watchWinch() chan os.Signal {
	ch := make(chan os.Signal, 1)
	signal.Notify(ch, syscall.SIGWINCH)
	return ch
}

var _ = os.Stdout

package main

import (
	"bufio"
	"strings"
)

// renderer implements the observed frame-diff terminal output protocol:
//   - first frame: "\r" + lines joined, each line "<content>\x1b[K", separated by "\r\n"
//   - subsequent frames: "\x1b[{n-1}A" to top; unchanged lines skipped with "\n";
//     changed lines rewritten "<content>\x1b[K\r\n" ("\r\n" omitted on last line)
//   - frame ends with "\x1b[{width}D"
//   - lines beyond terminal height are truncated; "\x1b[1A" style compression
type renderer struct {
	out        *bufio.Writer
	width      int
	height     int
	prevLines  []string
	initialized bool
}

func newRenderer(out *bufio.Writer) *renderer {
	return &renderer{out: out}
}

func (r *renderer) setSize(w, h int) { r.width, r.height = h, w } // placeholder, fixed below

func (r *renderer) flush(content string) {
	lines := strings.Split(content, "\n")
	// drop trailing empty lines like strings.TrimRight(content, "\n")?
	// (bubbletea trims trailing blank lines; verify against binary)
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	if r.height > 0 && len(lines) > r.height {
		lines = lines[:r.height]
	}
	var b strings.Builder
	if !r.initialized {
		b.WriteString("\r")
		r.initialized = true
	} else {
		if len(r.prevLines) > 1 {
			b.WriteString(cursorUp(len(r.prevLines) - 1))
		}
	}
	for i, line := range lines {
		if i < len(r.prevLines) && r.prevLines[i] == line {
			b.WriteString("\n")
			continue
		}
		b.WriteString(line)
		b.WriteString("\x1b[K")
		if i < len(lines)-1 {
			b.WriteString("\r\n")
		}
	}
	// lines removed since last frame: clear them
	if len(r.prevLines) > len(lines) {
		for i := len(lines); i < len(r.prevLines); i++ {
			if i > 0 || len(lines) > 0 {
				b.WriteString("\n")
			}
			b.WriteString("\x1b[K")
		}
	}
	b.WriteString(cursorLeft(r.width))
	r.out.WriteString(b.String())
	r.out.Flush()
	r.prevLines = lines
}

func (r *renderer) stop() {
	var b strings.Builder
	n := len(r.prevLines)
	if n > 1 {
		b.WriteString(cursorUp(n - 1))
	}
	for i := 0; i < n; i++ {
		b.WriteString("\n")
	}
	b.WriteString("\x1b[K")
	b.WriteString(cursorLeft(r.width))
	b.WriteString("\x1b[2K\r")
	r.out.WriteString(b.String())
	r.out.Flush()
	r.prevLines = nil
}

func cursorUp(n int) string {
	return "\x1b[" + itoa(n) + "A"
}

func cursorLeft(n int) string {
	if n <= 0 {
		n = 1
	}
	return "\x1b[" + itoa(n) + "D"
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [8]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

package main

// Key input parsing: reads bytes from the TTY and decodes them into key events,
// matching the escape sequences emitted by xterm-compatible terminals.

type keyType int

const (
	keyRune keyType = iota
	keyEnter
	keyBackspace
	keyEsc
	keyCtrlC
	keyUp
	keyDown
	keyLeft
	keyRight
	keyShiftUp
	keyShiftDown
	keyShiftLeft
	keyShiftRight
	keyDelete
	keyHome
	keyEnd
	keyPgUp
	keyPgDown
	keyCtrlD
	keyCtrlU
	keyCtrlW
	keyTab
	keyShiftTab
	keyCtrlA
	keyCtrlE
	keyCtrlK
	keyUnknown
	keyPaste // bracketed paste: text in pasteText
)

type keyEvent struct {
	typ  keyType
	r    rune
	text string // for paste events / multi-byte input
}

// parseKeys decodes a buffer of input bytes into key events, returning
// the events and any trailing partial escape sequence to keep for next read.
func parseKeys(buf []byte) ([]keyEvent, []byte) {
	var events []keyEvent
	for len(buf) > 0 {
		ev, n, incomplete := parseOne(buf)
		if incomplete {
			return events, buf
		}
		if n == 0 {
			n = 1 // skip undecodable byte
		}
		if ev.typ != keyUnknown {
			events = append(events, ev)
		}
		buf = buf[n:]
	}
	return events, nil
}

func parseOne(buf []byte) (keyEvent, int, bool) {
	b := buf[0]
	if b != 0x1b {
		switch b {
		case '\r':
			return keyEvent{typ: keyEnter}, 1, false
		case 0x7f:
			return keyEvent{typ: keyBackspace}, 1, false
		case 0x03:
			return keyEvent{typ: keyCtrlC}, 1, false
		case 0x04:
			return keyEvent{typ: keyCtrlD}, 1, false
		case 0x15:
			return keyEvent{typ: keyCtrlU}, 1, false
		case 0x17:
			return keyEvent{typ: keyCtrlW}, 1, false
		case 0x01:
			return keyEvent{typ: keyCtrlA}, 1, false
		case 0x05:
			return keyEvent{typ: keyCtrlE}, 1, false
		case 0x0b:
			return keyEvent{typ: keyCtrlK}, 1, false
		case '\t':
			return keyEvent{typ: keyTab}, 1, false
		}
		if b < 0x20 {
			return keyEvent{typ: keyUnknown}, 1, false
		}
		// decode UTF-8 rune
		r, size := decodeRune(buf)
		if size == 0 {
			return keyEvent{}, 0, true // incomplete UTF-8
		}
		return keyEvent{typ: keyRune, r: r}, size, false
	}
	// escape sequence
	if len(buf) == 1 {
		return keyEvent{}, 0, true // wait for more
	}
	if buf[1] == '[' || buf[1] == 'O' {
		// CSI / SS3: find final byte
		for i := 2; i < len(buf); i++ {
			c := buf[i]
			if c >= 0x40 && c <= 0x7e {
				return parseCSI(buf[2:i], c), i + 1, false
			}
			if i > 16 {
				break
			}
		}
		return keyEvent{}, 0, true // incomplete sequence
	}
	if buf[1] == ']' {
		// OSC - ignore
		for i := 2; i < len(buf); i++ {
			if buf[i] == 0x07 || (buf[i] == '\\' && buf[i-1] == 0x1b) {
				return keyEvent{typ: keyUnknown}, i + 1, false
			}
		}
		return keyEvent{}, 0, true
	}
	// Alt+key or bare ESC followed by something
	if len(buf) >= 2 {
		// treat as esc + key: emit esc now
		return keyEvent{typ: keyEsc}, 1, false
	}
	return keyEvent{}, 0, true
}

func parseCSI(params []byte, final byte) keyEvent {
	p := string(params)
	switch final {
	case 'A':
		if p == "1;2" || p == "2" {
			return keyEvent{typ: keyShiftUp}
		}
		return keyEvent{typ: keyUp}
	case 'B':
		if p == "1;2" || p == "2" {
			return keyEvent{typ: keyShiftDown}
		}
		return keyEvent{typ: keyDown}
	case 'C':
		if p == "1;2" || p == "2" {
			return keyEvent{typ: keyShiftRight}
		}
		return keyEvent{typ: keyRight}
	case 'D':
		if p == "1;2" || p == "2" {
			return keyEvent{typ: keyShiftLeft}
		}
		return keyEvent{typ: keyLeft}
	case 'H':
		return keyEvent{typ: keyHome}
	case 'F':
		return keyEvent{typ: keyEnd}
	case 'Z':
		return keyEvent{typ: keyShiftTab}
	case '~':
		switch p {
		case "3":
			return keyEvent{typ: keyDelete}
		case "5":
			return keyEvent{typ: keyPgUp}
		case "6":
			return keyEvent{typ: keyPgDown}
		case "1", "7":
			return keyEvent{typ: keyHome}
		case "4", "8":
			return keyEvent{typ: keyEnd}
		}
	}
	return keyEvent{typ: keyUnknown}
}

func decodeRune(buf []byte) (rune, int) {
	b := buf[0]
	if b < 0x80 {
		return rune(b), 1
	}
	var size int
	var r rune
	switch {
	case b&0xe0 == 0xc0:
		size, r = 2, rune(b&0x1f)
	case b&0xf0 == 0xe0:
		size, r = 3, rune(b&0x0f)
	case b&0xf8 == 0xf0:
		size, r = 4, rune(b&0x07)
	default:
		return 0xfffd, 1
	}
	if len(buf) < size {
		return 0, 0
	}
	for i := 1; i < size; i++ {
		r = r<<6 | rune(buf[i]&0x3f)
	}
	return r, size
}
